using System.Runtime.CompilerServices;
using DeskCanvas.App.Services;

internal static class V17ContractTests
{
 [ModuleInitializer] internal static void Run(){TimelineAndReconciliation();GlobalTransportFallback();ActivationFallback();InstallerContract();Console.WriteLine("PASS v1.7 reconciliation fallback activation and installer cleanup");}
 private static void TimelineAndReconciliation(){var data=Data("Long YouTube Title",581,1502,NowPlayingState.Playing,true,true,true);var session=new FakeSession(data);var manager=new FakeManager(session);var service=new NowPlayingService(new FakeProvider(manager),new FakeSender(),TimeSpan.FromMilliseconds(15));var lease=service.Acquire();Wait(()=>service.Snapshot.End==TimeSpan.FromSeconds(1502));Equal(TimeSpan.FromSeconds(581),service.Snapshot.Position);var observed=service.Snapshot; if(NowPlayingService.Project(observed,observed.ObservedAt.AddSeconds(2)).Position<TimeSpan.FromSeconds(582))throw new InvalidOperationException("playing projection failed");session.Value=Data("Long YouTube Title",0,0,NowPlayingState.Playing,false,false,false);session.RaiseTimeline();Wait(()=>service.Snapshot.End==TimeSpan.FromSeconds(1502));if(service.Snapshot.Position<TimeSpan.FromSeconds(581))throw new InvalidOperationException("transient zero erased timeline");session.Throw=true;session.RaiseTimeline();Thread.Sleep(25);Equal(TimeSpan.FromSeconds(1502),service.Snapshot.End);session.Throw=false;session.Value=Data("Long YouTube Title",1502,600,NowPlayingState.Playing,true,false,false);Wait(()=>service.Snapshot.Position>=TimeSpan.FromSeconds(600));session.Value=Data("Long YouTube Title",1502,601,NowPlayingState.Paused,true,false,false);session.RaisePlayback();Wait(()=>service.Snapshot.State==NowPlayingState.Paused);var paused=service.Snapshot;Equal(paused.Position,NowPlayingService.Project(paused,paused.ObservedAt.AddSeconds(3)).Position);session.Value=Data("Other Title",0,0,NowPlayingState.Paused,false,false,false);session.RaiseMedia();Wait(()=>service.Snapshot.Title=="Other Title");Equal(TimeSpan.Zero,service.Snapshot.End);manager.Current=null;manager.Raise();Wait(()=>!service.Snapshot.HasSession);service.Dispose();lease.Dispose();var reads=session.Reads;Thread.Sleep(50);Equal(reads,session.Reads);if(session.Handlers!=0||manager.Handlers!=0)throw new InvalidOperationException("timer or event lifetime leaked");}
 private static void GlobalTransportFallback(){var sender=new FakeSender();var session=new FakeSession(Data("Song",5,20,NowPlayingState.Playing,true,true,true));var service=new NowPlayingService(new FakeProvider(new FakeManager(session)),sender,TimeSpan.FromSeconds(10));using var lease=service.Acquire();Wait(()=>service.Snapshot.HasSession);session.Result=true;if(!service.NextAsync().GetAwaiter().GetResult()||sender.Calls!=0)throw new InvalidOperationException("successful GSMTC command used fallback");session.Result=false;if(!service.PreviousAsync().GetAwaiter().GetResult()||sender.Calls!=1)throw new InvalidOperationException("false command did not fallback");session.ThrowCommand=true;if(!service.NextAsync().GetAwaiter().GetResult()||sender.Calls!=2)throw new InvalidOperationException("throwing command did not fallback");service.Dispose();var noSessionSender=new FakeSender();var empty=new NowPlayingService(new FakeProvider(new FakeManager(null)),noSessionSender,TimeSpan.FromSeconds(10));using var emptyLease=empty.Acquire();Thread.Sleep(20);if(empty.NextAsync().GetAwaiter().GetResult()||noSessionSender.Calls!=0)throw new InvalidOperationException("null session used fallback");empty.Dispose();}
 private static void ActivationFallback(){var platform=new FakeActivation();var activation=new ActivationService(platform);if(!activation.TryActivate("Vendor.Player!App","Ignored Long Title","Artist" )||platform.Aumid!="Vendor.Player!App"||platform.Matches!=0)throw new InvalidOperationException("strict AUMID route failed");platform.Reset();if(!activation.TryActivate("browser.exe","Ignored Long Title","Artist")||platform.Process!="browser.exe"||platform.Matches!=0)throw new InvalidOperationException("process route failed");platform.Reset();if(!activation.TryActivate("FoDC299D809B9700","A Very Distinct Song Name","Artist")||platform.Matches!=1)throw new InvalidOperationException("unique title fallback failed");platform.Reset();platform.MatchResult=false;if(activation.TryActivate("not valid","short","" )||platform.Matches!=1)throw new InvalidOperationException("ambiguous/short input activated");}
 private static void InstallerContract(){var source=File.ReadAllText(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(SourcePath())!,"..","..","..","..","installer","DeskCanvas.v17.iss")));if(!source.Contains("AppId={{960134F4-96AD-4F8E-87C2-7AA30CE18E27}",StringComparison.Ordinal)||!source.Contains("[InstallDelete]",StringComparison.Ordinal)||!source.Contains("[Files]",StringComparison.Ordinal)||source.IndexOf("[InstallDelete]",StringComparison.Ordinal)>source.IndexOf("[Files]",StringComparison.Ordinal)||source.Contains("{localappdata}\\DeskCanvas",StringComparison.Ordinal)||source.Contains("unins",StringComparison.OrdinalIgnoreCase)&&source.Contains("[InstallDelete]",StringComparison.Ordinal)&&source.Contains("{app}\\unins",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("installer cleanup contract failed");}
 private static string SourcePath([CallerFilePath]string path="")=>path;private static NowPlayingData Data(string title,double end,double position,NowPlayingState state,bool seek,bool previous,bool next)=>new("FoDC299D809B9700",title,"Artist","Album",null,state,TimeSpan.FromSeconds(position),TimeSpan.FromSeconds(end),previous,true,next,seek);private static void Wait(Func<bool> condition){if(!SpinWait.SpinUntil(condition,TimeSpan.FromSeconds(3)))throw new TimeoutException("v1.7 async contract timed out");}private static void Equal<T>(T expected,T actual){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new InvalidOperationException($"expected {expected}, actual {actual}");}
 private sealed class FakeSender:IGlobalMediaCommandSender{internal int Calls;public bool IsAvailable=>true;public bool TrySend(NowPlayingCommand command){Calls++;return command is NowPlayingCommand.Previous or NowPlayingCommand.Next;}}
 private sealed class FakeActivation:IActivationPlatform{internal string? Aumid,Process;internal int Matches;internal bool MatchResult=true;public bool ActivateAumid(string value){Aumid=value;return true;}public bool ActivateProcess(string value){Process=value;return true;}public bool ActivateUniqueTitleMatch(string title,string artist){Matches++;return title.Length>=6&&MatchResult;}internal void Reset(){Aumid=Process=null;Matches=0;MatchResult=true;}}
 private sealed class FakeProvider(FakeManager manager):INowPlayingManagerProvider{public Task<INowPlayingManager> RequestAsync()=>Task.FromResult<INowPlayingManager>(manager);}private sealed class FakeManager(INowPlayingSession? current):INowPlayingManager{private EventHandler? changed;internal INowPlayingSession? Current=current;internal int Handlers=>changed?.GetInvocationList().Length??0;public INowPlayingSession? CurrentSession=>Current;public event EventHandler? CurrentSessionChanged{add=>changed+=value;remove=>changed-=value;}internal void Raise()=>changed?.Invoke(this,EventArgs.Empty);public void Dispose(){}}
 private sealed class FakeSession(NowPlayingData value):INowPlayingSession{private EventHandler? media,playback,timeline;internal NowPlayingData Value=value;internal bool Throw,ThrowCommand,Result=true;internal int Reads;internal int Handlers=>(media?.GetInvocationList().Length??0)+(playback?.GetInvocationList().Length??0)+(timeline?.GetInvocationList().Length??0);public event EventHandler? MediaPropertiesChanged{add=>media+=value;remove=>media-=value;}public event EventHandler? PlaybackInfoChanged{add=>playback+=value;remove=>playback-=value;}public event EventHandler? TimelinePropertiesChanged{add=>timeline+=value;remove=>timeline-=value;}internal void RaiseMedia()=>media?.Invoke(this,EventArgs.Empty);internal void RaisePlayback()=>playback?.Invoke(this,EventArgs.Empty);internal void RaiseTimeline()=>timeline?.Invoke(this,EventArgs.Empty);public Task<NowPlayingData> ReadAsync(){Reads++;return Throw?Task.FromException<NowPlayingData>(new InvalidOperationException()):Task.FromResult(Value);}public Task<bool> TryCommandAsync(NowPlayingCommand command,TimeSpan position=default){if(ThrowCommand)throw new InvalidOperationException();return Task.FromResult(Result);}public void Dispose(){}}
}
